/**
 * APIForge brand mark as a data URI, for edge-runtime image generators
 * (opengraph-image, twitter-image, /api/og) and the roast SVG badge.
 *
 * Source of truth: public/images/logo-mark.svg. Edge runtimes have no fs access,
 * so the file's bytes are inlined here (base64). If the SVG changes, regenerate with:
 *   base64 -w0 public/images/logo-mark.svg
 */
const APP_LOGO_SVG_BASE64 = "";

const APP_LOGO_DATA_URI = `data:image/svg+xml;base64,${APP_LOGO_SVG_BASE64}`;

export function getAppLogoBase64(): string {
  return APP_LOGO_DATA_URI;
}

/** Fire (roast) mark, 224px PNG, base64. Source: public/images/logo-fire.png (edge has no fs). */
const FIRE_LOGO_PNG_BASE64 =
  "";

export const FIRE_LOGO_DATA_URI = `data:image/png;base64,${FIRE_LOGO_PNG_BASE64}`;
